# Antes
def f(l):
    t = 0
    for x in l:
        if x > 100000:
            t = t + 1
    return t

# Después
TOPE_MENSUAL = 100000

def meses_sobre_tope(totales_mensuales):
    """Cuenta cuántos meses superaron el tope de gasto."""
    return len([total for total in totales_mensuales if total > TOPE_MENSUAL])

datos = [90000, 120000, 150000]
assert f(datos) == meses_sobre_tope(datos)
print(meses_sobre_tope(datos))
